#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "mvt.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// A: i x j  (row-major: j is inner, i is outer)
	DEFINE_PROTO_STRUCT(A_layout, j_vec ^ i_vec);
	// x*: vectors indexed by 'i'
	DEFINE_PROTO_STRUCT(x_layout, i_vec);
	// y*: vectors indexed by 'j'
	DEFINE_PROTO_STRUCT(y_layout, j_vec);
} tuning;

// initialization function
void init_array(auto x1, auto x2, auto y_1, auto y_2, auto A) {
	// x1, x2: length N in dim 'i'
	// y_1, y_2: length N in dim 'j'
	// A: i x j

	using namespace noarr;

	auto n = A | get_length<'i'>(); // N

	// Initialize x1
	traverser(x1).for_each([=](auto state) {
		auto i = get_index<'i'>(state);
		x1[state] = (num_t)((i % n)) / (num_t)n;
	});

	// Initialize x2
	traverser(x2).for_each([=](auto state) {
		auto i = get_index<'i'>(state);
		x2[state] = (num_t)(((i + 1) % n)) / (num_t)n;
	});

	// Initialize y_1
	traverser(y_1).for_each([=](auto state) {
		auto j = get_index<'j'>(state);
		y_1[state] = (num_t)(((j + 3) % n)) / (num_t)n;
	});

	// Initialize y_2
	traverser(y_2).for_each([=](auto state) {
		auto j = get_index<'j'>(state);
		y_2[state] = (num_t)(((j + 4) % n)) / (num_t)n;
	});

	// Initialize A
	traverser(A).for_each([=](auto state) {
		auto i = get_index<'i'>(state);
		auto j = get_index<'j'>(state);
		A[state] = (num_t)(((i * j) % n)) / (num_t)n;
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_mvt(auto x1, auto x2, auto y_1, auto y_2, auto A) {
	// First phase:
	// for (i)
	//   for (j)
	//     x1[i] = x1[i] + A[i][j] * y_1[j];
	//
	// Second phase:
	// for (i)
	//   for (j)
	//     x2[i] = x2[i] + A[j][i] * y_2[j];

	using namespace noarr;

#pragma scop
	// Phase 1: x1[i] += A[i][j] * y_1[j];
	traverser(x1, y_1, A).template for_dims<'i'>([=](auto inner) {
		inner.template for_each<'j'>([=](auto state) {
			// state has indices 'i' and 'j'
			x1[state] += A[state] * y_1[state];
		});
	});

	// Phase 2: x2[i] += A[j][i] * y_2[j];
	traverser(x2, y_2, A).template for_dims<'i'>([=](auto inner) {
		inner.template for_each<'j'>([=](auto state) {
			// state: ('i' = loop-i, 'j' = loop-j)
			auto i_idx = get_index<'i'>(state);
			auto j_idx = get_index<'j'>(state);

			// Build a state corresponding to A[j][i]
			auto a_state = noarr::idx<'i', 'j'>(j_idx, i_idx);

			x2[state] += A[a_state] * y_2[state];
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// describe common lengths
	auto set_lengths = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);

	// data structures
	auto A   = noarr::bag(noarr::scalar<num_t>() ^ tuning.A_layout ^ set_lengths);
	auto x1  = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout ^ set_lengths);
	auto x2  = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout ^ set_lengths);
	auto y_1 = noarr::bag(noarr::scalar<num_t>() ^ tuning.y_layout ^ set_lengths);
	auto y_2 = noarr::bag(noarr::scalar<num_t>() ^ tuning.y_layout ^ set_lengths);

	// initialize data
	init_array(x1.get_ref(), x2.get_ref(), y_1.get_ref(), y_2.get_ref(), A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_mvt(x1.get_ref(), x2.get_ref(), y_1.get_ref(), y_2.get_ref(), A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to avoid dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, x1.get_ref());
		noarr::serialize_data(std::cerr, x2.get_ref());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}

