// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "mvt.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// A: i x j
	DEFINE_PROTO_STRUCT(A_layout, j_vec ^ i_vec);
	// x1, x2: length N in 'i'
	DEFINE_PROTO_STRUCT(x_layout, i_vec);
	// y_1, y_2: length N in 'j'
	DEFINE_PROTO_STRUCT(y_layout, j_vec);
} tuning;

// initialization function
void init_array(auto x1, auto x2, auto y_1, auto y_2, auto A) {
	using namespace noarr;

	// All vectors have the same length in their respective dimensions
	auto n_i = x1 | get_length<'i'>();
	auto n_j = y_1 | get_length<'j'>();

	// Initialize x1[i] = (i % n) / n;
	traverser(x1).for_each([=](auto state) {
		auto i = get_index<'i'>(state);
		x1[state] = (num_t)((i % n_i)) / n_i;
	});

	// Initialize x2[i] = ((i + 1) % n) / n;
	traverser(x2).for_each([=](auto state) {
		auto i = get_index<'i'>(state);
		x2[state] = (num_t)(((i + 1) % n_i)) / n_i;
	});

	// Initialize y_1[j] = ((j + 3) % n) / n;
	traverser(y_1).for_each([=](auto state) {
		auto j = get_index<'j'>(state);
		y_1[state] = (num_t)(((j + 3) % n_j)) / n_j;
	});

	// Initialize y_2[j] = ((j + 4) % n) / n;
	traverser(y_2).for_each([=](auto state) {
		auto j = get_index<'j'>(state);
		y_2[state] = (num_t)(((j + 4) % n_j)) / n_j;
	});

	// Initialize A[i][j] = (i * j % n) / n;
	// Here n is N, the size in either dimension; both are equal.
	auto n = A | get_length<'i'>();

	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		A[state] = (num_t)((i * j % n)) / n;
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_mvt(auto x1, auto x2, auto y_1, auto y_2, auto A) {
	using namespace noarr;

	// x1: length N in 'i'
	// x2: length N in 'i'
	// y_1: length N in 'j'
	// y_2: length N in 'j'
	// A: N x N, dimensions 'i' x 'j'

#pragma scop
	// First loop nest:
	// for (i)
	//   for (j)
	//     x1[i] = x1[i] + A[i][j] * y_1[j];
	traverser(A, x1, y_1).template for_dims<'i'>([=](auto trav_i) {
		trav_i.for_each([=](auto state) {
			// state contains 'i' and 'j'
			x1[state] = x1[state] + A[state] * y_1[state];
		});
	});

	// Second loop nest:
	// for (i)
	//   for (j)
	//     x2[i] = x2[i] + A[j][i] * y_2[j];
	//
	// We keep the traversal order identical (outer i, inner j).
	// For A[j][i] we explicitly build a state with swapped indices.
	traverser(x2, y_2).template for_dims<'i'>([=](auto trav_i) {
		trav_i.for_each([=](auto state) {
			// state: 'i' is the outer-loop index, 'j' is the inner-loop index
			auto i = get_index<'i'>(state);
			auto j = get_index<'j'>(state);

			// Access A[j][i]:
			auto a_state = noarr::idx<'i', 'j'>(j, i);

			x2[state] = x2[state] + A[a_state] * y_2[state];
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// set lengths for all dimensions we are going to use
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// allocate data
	auto A   = noarr::bag(noarr::scalar<num_t>() ^ tuning.A_layout ^ set_lengths);
	auto x1  = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout ^ set_lengths);
	auto x2  = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout ^ set_lengths);
	auto y_1 = noarr::bag(noarr::scalar<num_t>() ^ tuning.y_layout ^ set_lengths);
	auto y_2 = noarr::bag(noarr::scalar<num_t>() ^ tuning.y_layout ^ set_lengths);

	// initialize data
	init_array(x1.get_ref(), x2.get_ref(), y_1.get_ref(), y_2.get_ref(), A.get_ref());

	// start timer
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_mvt(x1.get_ref(), x2.get_ref(), y_1.get_ref(), y_2.get_ref(), A.get_ref());

	// stop timer
	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, x1.get_ref());
		noarr::serialize_data(std::cerr, x2.get_ref());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
