	// Initialize x1, x2, y_1, y_2 (all length n)
	traverser(x1, x2, y_1, y_2).for_each([=](auto state) {
		auto i = get_index<'i'>(state);

		x1[state] = static_cast<num_t>((i % n)) / static_cast<num_t>(n);
		x2[state] = static_cast<num_t>(((i + 1) % n)) / static_cast<num_t>(n);
		y_1[state] = static_cast<num_t>(((i + 3) % n)) / static_cast<num_t>(n);
		y_2[state] = static_cast<num_t>(((i + 4) % n)) / static_cast<num_t>(n);
	});

	// Initialize A: i x j
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		A[state] = static_cast<num_t>(((i * j) % n)) / static_cast<num_t>(n);
	});
}

