	auto A_T = A ^ rename<'i', 'j', 'j', 'i'>();

#pragma scop
	// First loop nest:
	// for (i) for (j) x1[i] += A[i][j] * y_1[j];
	traverser(A, x1, y_1_j).template for_dims<'i'>([=](auto inner) {
		inner.template for_each<'j'>([=](auto state) {
			x1[state] = x1[state] + A[state] * y_1_j[state];
		});
	});

	// Second loop nest:
	// for (i) for (j) x2[i] += A[j][i] * y_2[j];
	traverser(A_T, x2, y_2_j).template for_dims<'i'>([=](auto inner) {
		inner.template for_each<'j'>([=](auto state) {
			x2[state] = x2[state] + A_T[state] * y_2_j[state];
		});
	});
#pragma endscop
}

} // namespace

