#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/traversers.hpp>

// include common definitions (Polybench sizes, DATA_TYPE, DEFINE_PROTO_STRUCT, bag, ...)
#include "defines.hpp"

// include benchmark-specific definitions (N, etc.)
#include "mvt.hpp"

using num_t = DATA_TYPE;

namespace {

// dimension prototypes
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

// layout tuning (separated so it can be changed independently of the algorithm)
struct tuning {
	// x1, x2: 1D vectors indexed by 'i'
	DEFINE_PROTO_STRUCT(x_layout, i_vec);

	// y_1, y_2: 1D vectors indexed by 'j'
	DEFINE_PROTO_STRUCT(y_layout, j_vec);

	// A: N x N matrix, row-major: i = row index, j = column index
	// we want 'j' to be the inner (contiguous) dimension
	DEFINE_PROTO_STRUCT(A_layout, j_vec ^ i_vec);
} tuning;

// Array initialization.
void init_array(auto x1, auto x2, auto y_1, auto y_2, auto A) {
	using namespace noarr;

	// All vectors/matrix have length N in each dimension
	auto n = x1 | get_length<'i'>();

	// Initialize x1 and x2 (dimension 'i')
	traverser(x1, x2).for_each([=](auto state) {
		auto i = get_index<'i'>(state);

		x1[state] = (num_t)(i % n) / n;
		x2[state] = (num_t)((i + 1) % n) / n;
	});

	// Initialize y_1 and y_2 (dimension 'j')
	traverser(y_1, y_2).for_each([=](auto state) {
		auto j = get_index<'j'>(state);

		y_1[state] = (num_t)((j + 3) % n) / n;
		y_2[state] = (num_t)((j + 4) % n) / n;
	});

	// Initialize A (dimensions 'i' x 'j')
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		A[state] = (num_t)((i * j) % n) / n;
	});
}

// Main computational kernel.
// Original C kernel:
//
// for (i = 0; i < N; i++)
//   for (j = 0; j < N; j++)
//     x1[i] = x1[i] + A[i][j] * y_1[j];
// for (i = 0; i < N; i++)
//   for (j = 0; j < N; j++)
//     x2[i] = x2[i] + A[j][i] * y_2[j];
//
[[gnu::flatten, gnu::noinline]]
void kernel_mvt(auto x1, auto x2, auto y_1, auto y_2, auto A) {
	using namespace noarr;

	// View of A with swapped dimension names to access A[j][i] as A_t[i][j]
	auto A_t = A ^ noarr::rename<'i', 'j', 'j', 'i'>();

#pragma scop
	// First double loop:
	// for (i) for (j) x1[i] += A[i][j] * y_1[j];
	traverser(A, x1, y_1).template for_dims<'i'>([=](auto inner) {
		inner.template for_each<'j'>([=](auto state) {
			// state contains 'i' and 'j'
			x1[state] = x1[state] + A[state] * y_1[state];
		});
	});

	// Second double loop:
	// for (i) for (j) x2[i] += A[j][i] * y_2[j];
	// Using A_t so that A_t[i,j] == A[j,i].
	traverser(A_t, x2, y_2).template for_dims<'i'>([=](auto inner) {
		inner.template for_each<'j'>([=](auto state) {
			x2[state] = x2[state] + A_t[state] * y_2[state];
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t n = N;

	// Set lengths for dimensions 'i' and 'j'
	auto set_lengths = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);

	// Allocate bags with the chosen layouts
	auto A   = noarr::bag(noarr::scalar<num_t>() ^ tuning.A_layout ^ set_lengths);
	auto x1  = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout ^ set_lengths);
	auto x2  = noarr::bag(noarr::scalar<num_t>() ^ tuning.x_layout ^ set_lengths);
	auto y_1 = noarr::bag(noarr::scalar<num_t>() ^ tuning.y_layout ^ set_lengths);
	auto y_2 = noarr::bag(noarr::scalar<num_t>() ^ tuning.y_layout ^ set_lengths);

	// Initialize arrays
	init_array(x1.get_ref(), x2.get_ref(), y_1.get_ref(), y_2.get_ref(), A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_mvt(x1.get_ref(), x2.get_ref(), y_1.get_ref(), y_2.get_ref(), A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Prevent dead-code elimination: print x1 and x2 when requested
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, x1.get_ref());
		noarr::serialize_data(std::cerr, x2.get_ref());
	}

	// Print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
